def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    nonbg = [v for v in counts if v != bg]
    marker = min(nonbg, key=lambda v: counts[v])
    bar = next(v for v in nonbg if v != marker)
    out = [row[:] for row in grid]

    def project(coords):
        # coords lists cells along a ray, ordered from the edge inward
        seed = next((i for i, (r, c) in enumerate(coords)
                     if grid[r][c] == marker), None)
        stop = seed if seed is not None else len(coords)
        for r, c in coords[:stop]:
            out[r][c] = marker
        if seed is not None:
            r, c = coords[seed]
            out[r][c] = 4

    # Each contiguous boundary bar cell projects inward along its row/column.
    for r in range(h):
        if grid[r][0] == bar:
            project([(r, c) for c in range(1, w)])
        if grid[r][w-1] == bar:
            project([(r, c) for c in range(w-2, -1, -1)])
    for c in range(w):
        if grid[0][c] == bar:
            project([(r, c) for r in range(1, h)])
        if grid[h-1][c] == bar:
            project([(r, c) for r in range(h-2, -1, -1)])

    return out
